// eslint-disable
'use strict';

// Указываем набор полей при создании логгера
const logger = require('@yandex-int/yandex-logger')({
    fields: {
        a: 1,
    },
});

// Создаем дочерний логгер и расширяем набор полей
const childLogger = logger.child({ a: 2, b: 1 });
childLogger.info('childLogger');

// Расширяем набор полей в существующем логгере
logger.extendFields({ a: 3, c: 1 });
logger.info('logger');

// Создаем дочерний логгер на каждый запрос
let req = require('./entry').req;
const loggerWithReq = logger.child({ req });
loggerWithReq.info('loggerWithReq');
